def solve(data):
    base = data['base']
    n = data['n']

    # Check for edge cases
    if n == 0:
        return '0'

    # Convert to the target base
    result = ''
    while n > 0:
        remainder = n % base
        if remainder >= 10:
            result = chr(remainder - 10 + ord('a')) + result
        else:
            result = str(remainder) + result
        n //= base

    return result
